head.b:skin:
/* 
THEME: Empathy Engine (Sage & Serenity Edition)
SYSTEM: Psychological Reflection & Counseling Framework
*/
:root {
    --sage: #86a789;
    --soft-green: #d2e3c8;
    --warm-cream: #fcfaf1;
    --deep-forest: #4f6f52;
    --text-dark: #3a4d39;
}
body {
    background-color: var(--soft-green);
    color: var(--text-dark);
    font-family: 'Inter', 'Segoe UI', sans-serif;
    margin: 0; padding: 0;
}
.header-wrap {
    background: linear-gradient(135deg, var(--deep-forest), var(--sage));
    color: var(--warm-cream);
    padding: 60px 20px;
    text-align: center;
    border-bottom: 5px solid var(--sage);
}
.main-container {
    max-width: 850px;
    margin: -40px auto 60px;
    padding: 20px;
}
.empathy-card {
    background: var(--warm-cream);
    border-radius: 24px;
    box-shadow: 0 10px 40px rgba(58, 77, 57, 0.15);
    padding: 35px;
    margin-bottom: 25px;
    border: 1px solid var(--sage);
}
.input-group { margin-bottom: 25px; }
.input-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 10px;
    color: var(--deep-forest);
    font-size: 15px;
    letter-spacing: 0.5px;
}
.input-group input, .input-group textarea {
    width: 100%;
    padding: 15px;
    border: 1.5px solid var(--sage);
    border-radius: 12px;
    font-family: inherit;
    box-sizing: border-box;
    background: #ffffff;
    transition: all 0.3s ease;
}
.input-group input:focus, .input-group textarea:focus {
    outline: none;
    border-color: var(--deep-forest);
    box-shadow: 0 0 8px rgba(79, 111, 82, 0.2);
}
.input-group textarea { height: 130px; resize: none; }

.lang-options { display: flex; gap: 25px; margin-top: 5px; }
.lang-item { display: flex; align-items: center; cursor: pointer; font-weight: 500; }
.lang-item input { width: auto; margin-right: 10px; accent-color: var(--deep-forest); }

h2 { color: var(--deep-forest); text-align: center; margin-top: 0; font-weight: 700; }

.copy-btn {
    background: var(--deep-forest);
    color: white;
    border: none;
    padding: 18px;
    cursor: pointer;
    font-weight: 600;
    border-radius: 15px;
    width: 100%;
    transition: 0.4s ease;
    font-size: 16px;
    box-shadow: 0 6px 12px rgba(79, 111, 82, 0.2);
}
.copy-btn:hover { background: var(--sage); transform: translateY(-2px); }
footer { text-align: center; color: var(--deep-forest); padding: 30px; font-size: 13px; opacity: 0.8; }

body.script:
function copyPrompt() {
    var title = document.getElementById("inputTitle").value || "Seseorang yang butuh didengarkan";
    var notes = document.getElementById("inputNotes").value || "Hanya ingin berbagi apa yang dirasakan.";

    var selectedLang = document.querySelector('input[name="lang"]:checked').value;
    var template = (selectedLang === 'id') ? 
                   document.getElementById("templateID").innerText : 
                   document.getElementById("templateEN").innerText;

    var finalPrompt = template.replace("[USER_TITLE]", title).replace("[USER_NOTES]", notes);

    var tempElem = document.createElement("textarea");
    tempElem.value = finalPrompt;
    document.body.appendChild(tempElem);
    tempElem.select();
    document.execCommand("copy");
    document.body.removeChild(tempElem);

    alert("🌿 Prompt Empati (" + (selectedLang === 'id' ? 'Indonesia' : 'English') + ") telah disalin. Semoga harimu lebih tenang.");
}
